import { getAdminCatalogAlbumTracks } from '../../src/administration/catalog/adminCatalogAlbumTracks';
import { applyCatalogReview, decideCatalogReviewIdentities, getCatalogReviewCandidates } from '../../src/administration/catalog/adminCatalogReviewApply';
import { reviewCreditId } from '../../src/administration/catalog/adminCatalogReviewCredits';
import { followArtist } from '../../src/services/listener/artistFollowService';
import { resolveFollowedArtistReleases } from '../../src/services/listener/followedArtistReleasesService';
import { getListenerArtist, getListenerOrganization } from '../../src/services/listener/listenerContentService';
import { adminImportIndexes, importCollection, initializeAdminImportStorage, withImportAdmin } from '../../src/administration/import/adminImportService';
import { importCandidateRevision, importIdentityCandidates } from '../../src/administration/import/adminImportIdentity';
import { chooseCatalogReviewLookup, resolveCatalogReviewLookup, retryCatalogReviewLookup, submitCatalogReviewLookup } from '../../src/administration/lookup/catalogReviewLookupRequests';
import type { CatalogReviewField, CatalogReviewIdentityResponse, CatalogReviewResponse } from '../../src/administration/catalog/adminCatalogReviewContract';
import type { ImportDraftV2 } from '../../src/administration/import/adminImportDraft';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';
import type { LookupExchange } from '../support/metadataLookupFixtures';
import { creditedRelease, drainLookup, lookupMbid, reviewSearch, reviewSearches, withLookup, type CreditedArtist } from '../support/catalogReviewRunFixtures';

let harness: MongoReplicaSetHarness, server: Server, base = '', token = '', userToken = '';
const actor = new ObjectId(), other = new ObjectId(), user = new ObjectId(), album = new ObjectId(), artist = new ObjectId(), first = new ObjectId(), second = new ObjectId();
const db = () => getDb()!, mutation = (revision: number) => ({ operationId: randomUUID(), expectedRevision: revision });
const code = (expected: string) => (error: any) => error.code === expected;
const field = (name: CatalogReviewField['field'], slotId: string | null = null): CatalogReviewField => ({ scope: slotId === null ? 'album' : 'track', slotId, field: name });
const request = (path: string, method = 'GET', body?: unknown, access = token, viewer?: string) => fetch(base + '/api/admin/v1' + path, { method,
    headers: { ...(access ? { Authorization: `Bearer ${access}` } : {}), 'Content-Type': 'application/json', ...(viewer ? { 'X-Finitude-Account-Viewer': viewer } : {}) },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
const current = (id: string) => getCatalogReview(String(actor), id);
const candidatesOf = (id: string) => getCatalogReviewCandidates(String(actor), id);
const record = async (collection: string, id: ObjectId | string) => (await db().collection(collection).findOne({ _id: typeof id === 'string' ? new ObjectId(id) : id }))!;
/** Every catalog collection an apply may write, and the identity fence, as one comparable value. */
const catalogState = async () => JSON.stringify(await Promise.all(['albums', 'audioTracks', 'artists', 'organizations', 'adminImportAnalysisSlots']
    .map(async name => [name, await db().collection(name).find({}).sort({ _id: 1 }).toArray()])));

