/** A review created now whose submitted lookup run completed on `exchanges`, so the worker applied its exact-count preselection. */
async function completedReview(exchanges: LookupExchange[]) {
    const created = await createCatalogReview(String(actor), { operationId: randomUUID(), albumId: String(album), expectedRevision: adminCatalogItemRevision('album', await record('albums', album)), another: true });
    const id = created.item.id;
    await submitCatalogReviewLookup(String(actor), id, { ...mutation(1), kind: 'album', text: 'Existing Album' });
    await drainLookup(exchanges);
    return { id, _id: new ObjectId(id), slots: created.item.source.tracks.map(track => track.slotId) };
}
/** The release run of a review of the default Album (release `1`), crediting `tracks` per track and `releaseArtists`/`label` as given. */
const run = (options: Parameters<typeof creditedRelease>[1] = {}) => [...reviewSearches([[lookupMbid(1), (options.tracks ?? [null, null]).length]]), ...creditedRelease(lookupMbid(1), options)];
/** What a confirmation of `lists` and `label` shows: the preselections and ID writes of the identities with an entry in a selected list, and the label's. */
function shownFor(candidates: CatalogReviewIdentityResponse, lists: readonly string[], label: boolean) {
    const scoped = new Set(candidates.identities.filter(row => row.entries.some(entry => lists.includes(entry.path))).map(row => row.id));
    return { preselections: candidates.preselections.filter(item => item.scope === 'label' ? label : scoped.has(item.identity!)),
        musicBrainzIds: candidates.musicBrainzIds.filter(item => item.scope === 'label' ? label : scoped.has(item.identity!)) };
}
/** Applies `fields` and `members` with what a confirmation read now shows for them, and the value revision it read. */
async function applyShown(id: string, fields: CatalogReviewField[], members: string[] = [], extra: Record<string, unknown> = {}) {
    const read = await candidatesOf(id);
    const shown = shownFor(read, [...(fields.some(item => item.field === 'artists') ? ['album.artists'] : []), ...members.map(slotId => `tracks.${slotId}.artists`)],
        fields.some(item => item.field === 'label'));
    return applyCatalogReview(String(actor), id, { ...mutation((await current(id)).item.revision), fields, memberCredits: members, ...shown, expectedValueRevision: read.valueRevision, ...extra });
}
/** Answers the applied candidate's conflicts on `paths` with `answer`, at their current values. */
async function answer(id: string, paths: string[], value: 'mine' | 'lookup' = 'mine'): Promise<CatalogReviewResponse> {
    const review = await current(id), draft = review.item.draft as any;
    const at = (path: string) => { const [scope, slot, name] = path.split('.'); return scope === 'album' ? draft.album[slot] : draft.tracks.find((track: any) => track.slotId === slot)[name]; };
    return resolveCatalogReviewLookup(String(actor), id, { ...mutation(review.item.revision), run: 1, candidateKey: `musicbrainz:${lookupMbid(1)}`,
        answers: paths.map(path => ({ path, answer: value, base: at(path) })) });
}
const singer: CreditedArtist = [lookupMbid(50), 'Track Singer'], held: CreditedArtist = [lookupMbid(51), 'Held Singer'];

test('candidates and decisions routes guard authentication, the current admin and the viewer, stay private, take 768 KB in any letter case, and decisions replay unlisted', () => withLookup(async () => {
    const { id } = await completedReview(run({ tracks: [[singer], [singer]] }));
    for (const [method, path] of [['GET', `/catalog-reviews/${id}/candidates`], ['POST', `/catalog-reviews/${id}/decisions`]] as const) {
        const anonymous = await request(path, method, method === 'POST' ? mutation(1) : undefined, '');
        assert.deepEqual([anonymous.status, anonymous.headers.get('cache-control')], [401, 'private, no-store'], path);
        assert.equal((await request(path, method, method === 'POST' ? mutation(1) : undefined, userToken)).status, 403, path);
        // A cookie session whose viewer header names another account is refused before anything is read (a cookie mutation is
        // refused even earlier, by request protection).
        const mismatched = await fetch(base + '/api/admin/v1' + path, { method, headers: { Cookie: `session_token=${token}`, 'X-Finitude-Account-Viewer': String(other), 'Content-Type': 'application/json' },
            ...(method === 'POST' ? { body: JSON.stringify(mutation(1)) } : {}) });
        assert.equal(mismatched.status, method === 'GET' ? 409 : 403, path);
    }
    const read = await request(`/catalog-reviews/${id}/candidates`);
    assert.match(read.headers.get('cache-control')!, /no-store/);
    const shown = await read.json() as CatalogReviewIdentityResponse;
    assert.deepEqual(Object.keys(shown).sort(), ['album', 'candidates', 'identities', 'keptTracklist', 'label', 'members', 'musicBrainzIds', 'preselections', 'revision', 'selection', 'valueRevision']);
    // Bodies up to 768 KB reach the parser (here refused for an unknown key); 800 KB is refused for its size, whatever the case.
    const revision = (await current(id)).item.revision;
    for (const path of ['apply', 'APPLY', 'decisions', 'Decisions']) {
        const parsed = await request(`/catalog-reviews/${id}/${path}`, 'POST', { ...mutation(revision), padding: 'p'.repeat(700 * 1024) });
        assert.deepEqual([parsed.status, await parsed.json()], [400, { code: 'ADMIN_IMPORT_INVALID_INPUT' }], path);
        assert.equal((await request(`/catalog-reviews/${id}/${path}`, 'POST', { ...mutation(revision), padding: 'p'.repeat(800 * 1024) })).status, 413, path);
    }
    // Every other review body stays at 96 KB.
    assert.equal((await request(`/catalog-reviews/${id}/analyze`, 'POST', { ...mutation(revision), padding: 'p'.repeat(100 * 1024) })).status, 413);
    // An empty decision set is a `decisions` receipt that replays and that the detail never lists.
    const body = { ...mutation(revision), decisions: [] };
    const decided = await request(`/catalog-reviews/${id}/decisions`, 'POST', body), value = await decided.json();
    assert.deepEqual([decided.status, value.receipt.kind, value.item.receipts.map((item: { kind: string }) => item.kind)], [200, 'decisions', ['create']]);
    assert.deepEqual(await (await request(`/catalog-reviews/${id}/decisions`, 'POST', body)).json(), value);
}));

test('applying fills Artist entries, the label, member Credits from their own tracks and the expected tracklist, creating and reusing records with their IDs, once across retries', () => withLookup(async () => {
    await db().collection('audioTracks').updateOne({ _id: second }, { $set: { attributionStatus: 'unknown' } });
    const holder = new ObjectId();
    await db().collection('artists').insertOne({ _id: holder, name: 'Held Singer', lifecycleStatus: 'ready', visibility: 'public', musicBrainzId: held[0] });
    const { id, _id, slots } = await completedReview(run({ tracks: [[singer], [held]] }));
    const shown = await candidatesOf(id);
    const row = (musicBrainzId: string) => shown.identities.find(item => item.musicBrainzId === musicBrainzId)!;
    // The Album's entry is bound to its credited Artist, which records the ID; a member-only artist is created, one whose ID a record keeps is reused.
    assert.deepEqual([row(lookupMbid(30)).state, row(lookupMbid(30)).bound.map(item => [item.id, item.visibility]), row(lookupMbid(30)).musicBrainzIdWrite?.replaces],
        ['bound', [[String(artist), 'hidden']], null]);
    assert.deepEqual([row(singer[0]).state, row(singer[0]).preselection?.action, row(singer[0]).needsAnswer, row(singer[0]).entries.map(entry => entry.slotId)], ['unbound', 'create-distinct', false, [slots[0]]]);
    assert.deepEqual([row(held[0]).preselection?.action, row(held[0]).preselection?.candidateId, row(held[0]).musicBrainzIdWrite], ['reuse', String(holder), null]);
    assert.deepEqual([shown.label?.state, shown.label?.preselection?.action, shown.label?.musicBrainzIdWrite?.musicBrainzId], ['unbound', 'create-distinct', lookupMbid(40)]);
    // The confirmation lists each member whose Credits change, with its attribution state.
    assert.deepEqual(shown.members.map(item => [item.slotId, item.credits, item.attribution, item.next.map(credit => [credit.name, credit.role, credit.subjectId === null])]), [
        [slots[0], true, { from: null, to: 'documented' }, [['Track Singer', 'primary', true]]], [slots[1], true, { from: 'unknown', to: 'documented' }, [['Held Singer', 'primary', false]]]]);
    assert.deepEqual([shown.album?.credits, shown.album?.next.map(credit => credit.name), shown.album?.replacedPrimaryArtistIds], [true, ['Existing Artist', 'Looked Up Label'], []]);
    const fields = [field('artists'), field('label'), field('expectedTracklist'), ...slots.map(slotId => field('discNumber', slotId))];
    const body = { ...mutation((await current(id)).item.revision), fields, memberCredits: slots, preselections: shown.preselections, musicBrainzIds: shown.musicBrainzIds,
        expectedValueRevision: shown.valueRevision };
    const applied = await applyCatalogReview(String(actor), id, body);
    assert.deepEqual([applied.item.state, applied.receipt?.kind, applied.item.applied?.fields.length], ['applied', 'apply', 5]);
    const created = (await db().collection('artists').findOne({ name: 'Track Singer' }))!, label = (await db().collection('organizations').findOne({ name: 'Looked Up Label' }))!;
    assert.deepEqual([created.musicBrainzId, created.visibility, created.albumIds, created.lifecycleStatus], [singer[0], 'hidden', [], 'ready']);
    assert.deepEqual([label.musicBrainzId, label.visibility, label.organizationType], [lookupMbid(40), 'hidden', 'label']);
    const existing = await record('artists', artist), albumAfter = await record('albums', album);
    assert.deepEqual([existing.musicBrainzId, existing.albumIds], [lookupMbid(30), [String(album)]]);
    assert.deepEqual(albumAfter.credits.map((credit: any) => [credit.subjectId, credit.role, credit.order]), [[String(artist), 'primary', 0], [String(label._id), 'label', 1]]);
    assert.deepEqual([albumAfter.attributionStatus, albumAfter.creditRevision, albumAfter.expectedTracklist.source, albumAfter.expectedTracklist.rows.length], ['documented', 1, 'musicbrainz', 2]);
    // Each member takes its own track's artist, never the Album's, and becomes documented.
    const tracks = [await record('audioTracks', first), await record('audioTracks', second)];
    assert.deepEqual(tracks.map(track => [track.credits.map((credit: any) => [credit.subjectId, credit.role]), track.attributionStatus, track.artistIds, track.discNumber]),
        [[[[String(created._id), 'primary']], 'documented', [String(created._id)], 1], [[[String(holder), 'primary']], 'documented', [String(holder)], 1]]);
    assert.deepEqual([(await record('artists', holder)).musicBrainzId, (await db().collection('adminImportAnalysisSlots').findOne({ _id: 'identity' as any }))?.revision], [held[0], 1]);
    assert.deepEqual((await importCollection().findOne({ _id }))!.catalogApplied?.memberCredits, slots);
    // The same intent replays and mints nothing again.
    const state = await catalogState();
    assert.deepEqual(await applyCatalogReview(String(actor), id, body), applied);
    assert.equal(await catalogState(), state);
    assert.deepEqual([await db().collection('artists').countDocuments({ name: 'Track Singer' }), await db().collection('organizations').countDocuments()], [1, 1]);
}));

test('a decorated primary Artist agrees with a release credited to its first part: applying keeps the Artist and its name, records the release\'s MusicBrainz ID and needs no decision', () => withLookup(async () => {
    const decorated = '合成情緒 -Gouseijoucho-';
    await db().collection('artists').updateOne({ _id: artist }, { $set: { name: decorated } });
    const { id, _id } = await completedReview([reviewSearch({ release: 'Existing Album', artist: '合成情緒' }, [[lookupMbid(1), 2]]),
        reviewSearch({ release: 'Existing Album' }, [[lookupMbid(1), 2]]), reviewSearch({ release: 'Existing Album', artist: decorated }, []),
        ...creditedRelease(lookupMbid(1), { releaseArtists: [[lookupMbid(30), '合成情緒']], label: null })]);
    // The run searched the first part first, preselected the release without a flag and raised no Artist conflict.
    const stored = (await db().collection('adminImportLookups').findOne({ _id }))!;
    assert.deepEqual([stored.queries.map((query: { query: unknown }) => query.query), stored.ranking.preselection?.artistMismatch, stored.applied.candidateKey,
        stored.applied.conflicts.map((item: { path: string }) => item.path).filter((path: string) => path.endsWith('.artists'))], [[{ release: 'Existing Album', artist: '合成情緒' },
        { release: 'Existing Album' }, { release: 'Existing Album', artist: decorated }], false, `musicbrainz:${lookupMbid(1)}`, []]);
    assert.deepEqual((await current(id)).item.draft.album.artists.map(entry => [entry.name, entry.musicBrainzId]), [[decorated, lookupMbid(30)]]);
    // The entry is bound to its captured Artist, which records the ID; nothing needs a decision.
    const shown = await candidatesOf(id), row = shown.identities.find(item => item.musicBrainzId === lookupMbid(30))!;
    assert.deepEqual([row.state, row.bound.map(item => item.id), row.needsAnswer, row.musicBrainzIdWrite?.musicBrainzId], ['bound', [String(artist)], false, lookupMbid(30)]);
    const applied = await applyShown(id, [field('artists')]);
    assert.equal(applied.item.state, 'applied');
    const kept = await record('artists', artist);
    assert.deepEqual([kept.name, kept.musicBrainzId, await db().collection('artists').countDocuments()], [decorated, lookupMbid(30), 1]);
    assert.deepEqual((await record('albums', album)).credits.map((credit: any) => [credit.subjectId, credit.role]), [[String(artist), 'primary']]);
}));

test('an editor that sends fields only applies them without Credits, records, IDs, tracklist or identity fence', () => withLookup(async () => {
    const { id, _id } = await completedReview(run({ tracks: [[singer], [singer]] }));
    await answer(id, ['album.title']);
    const before = await catalogState(), applied = await applyCatalogReview(String(actor), id, { ...mutation((await current(id)).item.revision), fields: [field('title')] });
    assert.deepEqual([applied.item.state, (await record('albums', album)).title], ['applied', 'Existing Album']);
    // The receipt is stored as before: no member list.
    assert.deepEqual(Object.keys((await importCollection().findOne({ _id }))!.catalogApplied!).sort(), ['at', 'fields', 'operationId']);
    const after = JSON.parse(await catalogState()), prior = JSON.parse(before);
    // Only the Album's own write fence and revision moved: its Credits, the Artists, Organizations, members and the fence did not.
    for (const index of [2, 3, 4]) assert.deepEqual(after[index], prior[index]);
    assert.deepEqual(after[0][1][0].credits, prior[0][1][0].credits);
    assert.deepEqual(after[1][1].map((track: any) => track.credits), prior[1][1].map((track: any) => track.credits));
    assert.equal(after[0][1][0].expectedTracklist, undefined);
}));

test('a name candidate needs an explicit decision, a candidate that appears after the confirmation read shows its row again, and a decided record that changed is stale', () => withLookup(async () => {
    const named = new ObjectId(), namedArtist: CreditedArtist = [lookupMbid(52), 'Named Singer'], fresh: CreditedArtist = [lookupMbid(53), 'Fresh Singer'];
    await db().collection('artists').insertOne({ _id: named, name: 'Named Singer', lifecycleStatus: 'ready', visibility: 'public' });
    const { id, slots } = await completedReview(run({ tracks: [[namedArtist], [fresh]] })), lists = slots.map(slotId => `tracks.${slotId}.artists`);
    let shown = await candidatesOf(id);
    const rowOf = (value: CatalogReviewIdentityResponse, musicBrainzId: string) => value.identities.find(row => row.musicBrainzId === musicBrainzId)!;
    assert.deepEqual([rowOf(shown, namedArtist[0]).needsAnswer, rowOf(shown, namedArtist[0]).preselection, rowOf(shown, fresh[0]).preselection?.action], [true, null, 'create-distinct']);
    const candidate = shown.candidates.items.find(item => item.id === String(named))!;
    assert.equal(candidate.match, 'name');
    const before = await catalogState();
    await assert.rejects(applyShown(id, [], slots), code('ADMIN_IMPORT_REVIEW_REQUIRED'));
    assert.equal(await catalogState(), before);
    const decide = async (decisions: unknown[]) => decideCatalogReviewIdentities(String(actor), id, { ...mutation((await current(id)).item.revision), decisions });
    const reuse = { scope: 'artist', identity: rowOf(shown, namedArtist[0]).id, boundName: 'Named Singer', action: 'reuse', candidateId: String(named), candidateRevision: candidate.revision };
    const stored = async () => (await importCollection().findOne({ _id: new ObjectId(id) }))!.catalogIdentityDecisions;
    await assert.rejects(decide([{ ...reuse, boundName: 'Named Singer Earlier' }]), code('ADMIN_IMPORT_DECISION_STALE'));
    // A well-formed handle naming no identity of the review (as after a lookup application replaced it) is stale, never malformed.
    await assert.rejects(decide([{ ...reuse, identity: randomUUID() }]), code('ADMIN_IMPORT_DECISION_STALE'));
    await assert.rejects(decide([{ ...reuse, candidateRevision: 'f'.repeat(64) }]), code('ADMIN_IMPORT_DUPLICATE_STALE'));
    // Replacing needs a record keeping another ID.
    await assert.rejects(decide([{ ...reuse, action: 'replace' }]), code('ADMIN_IMPORT_DUPLICATE_STALE'));
    assert.equal(await stored(), undefined);
    const decided = await decide([reuse]);
    assert.deepEqual([decided.receipt?.kind, (await stored())?.map(item => [item.identity, item.boundMusicBrainzId])], ['decisions', [[reuse.identity, namedArtist[0]]]]);
    shown = await candidatesOf(id);
    assert.deepEqual([rowOf(shown, namedArtist[0]).needsAnswer, rowOf(shown, namedArtist[0]).decision?.candidateId, rowOf(shown, namedArtist[0]).musicBrainzIdWrite],
        [false, String(named), { scope: 'artist', identity: reuse.identity, musicBrainzId: namedArtist[0], replaces: null }]);
    // A record named like the created artist appears after the read: the apply shows its row again and writes nothing.
    const later = new ObjectId();
    await db().collection('artists').insertOne({ _id: later, name: 'Fresh Singer', lifecycleStatus: 'ready', visibility: 'public' });
    const stale = shownFor(shown, lists, false), prior = await catalogState();
    await assert.rejects(applyCatalogReview(String(actor), id, { ...mutation((await current(id)).item.revision), fields: [], memberCredits: slots, ...stale, expectedValueRevision: shown.valueRevision }),
        code('ADMIN_IMPORT_REVIEW_REQUIRED'));
    assert.equal(await catalogState(), prior);
    shown = await candidatesOf(id);
    assert.deepEqual([rowOf(shown, fresh[0]).needsAnswer, rowOf(shown, fresh[0]).preselection], [true, null]);
    await decide([reuse, { scope: 'artist', identity: rowOf(shown, fresh[0]).id, boundName: 'Fresh Singer', action: 'create-distinct', candidateId: null, candidateRevision: null }]);
    // A decided record that changed since its decision is stale: the confirmation shows its row again, and the apply refuses it;
    // once it is as decided again, the apply is admitted.
    assert.equal(rowOf(await candidatesOf(id), namedArtist[0]).needsAnswer, false);
    await db().collection('artists').updateOne({ _id: named }, { $set: { name: 'Named Singer Renamed' } });
    assert.deepEqual([rowOf(await candidatesOf(id), namedArtist[0]).needsAnswer, rowOf(await candidatesOf(id), fresh[0]).needsAnswer], [true, false]);
    await assert.rejects(applyShown(id, [], slots), code('ADMIN_IMPORT_DUPLICATE_STALE'));
    await db().collection('artists').updateOne({ _id: named }, { $set: { name: 'Named Singer' } });
    const applied = await applyShown(id, [], slots);
    assert.equal(applied.item.state, 'applied');
    const created = (await db().collection('artists').find({ name: 'Fresh Singer' }).toArray()).find(item => !item._id.equals(later))!;
    assert.deepEqual([(await record('artists', named)).musicBrainzId, created.musicBrainzId, (await record('artists', later)).musicBrainzId], [namedArtist[0], fresh[0], undefined]);
    assert.deepEqual([(await record('audioTracks', first)).credits[0].subjectId, (await record('audioTracks', second)).credits[0].subjectId], [String(named), String(created._id)]);
}));

test('a captured Artist or a member\'s Artist renamed during the review makes it stale and nothing is written; an ID holder appearing shows the row again, and one not ready is an identity change', () => withLookup(async () => {
    const memberSinger = new ObjectId();
    await db().collection('artists').insertOne({ _id: memberSinger, name: 'Member Singer', lifecycleStatus: 'ready', visibility: 'public' });
    await db().collection('audioTracks').updateOne({ _id: first }, { $set: { attributionStatus: 'documented', credits: [{ creditId: 'member_primary', subjectType: 'artist', subjectId: String(memberSinger), role: 'primary', order: 0 }] } });
    const { id } = await completedReview(run({ tracks: [[[lookupMbid(56), 'Member Singer']], [singer]] }));
    const shown = await candidatesOf(id);
    // The agreeing Album entry only gains its ID: applying it changes no Artist Credit (the filled label adds one) and records the ID.
    const artistCredits = (credits: CatalogReviewIdentityResponse['members'][number]['next'] = []) => credits.filter(credit => credit.subjectType === 'artist');
    assert.deepEqual([artistCredits(shown.album?.next), shown.musicBrainzIds.filter(write => write.musicBrainzId === lookupMbid(30)).length], [artistCredits(shown.album?.current), 1]);
    // The confirmation read before the catalog changes below, so each refusal is the apply's own.
    const applyArtists = async () => applyCatalogReview(String(actor), id, { ...mutation((await current(id)).item.revision), fields: [field('artists')],
        ...shownFor(shown, ['album.artists'], false), expectedValueRevision: shown.valueRevision });
    const before = await catalogState();
    // Another ready record took the ID since the read: the write is no longer computed, so the row is shown again.
    const holder = new ObjectId();
    await db().collection('artists').insertOne({ _id: holder, name: 'Ready Holder', lifecycleStatus: 'ready', musicBrainzId: lookupMbid(30) });
    await assert.rejects(applyArtists(), code('ADMIN_IMPORT_REVIEW_REQUIRED'));
    // A holder that is not ready is not a candidate, but the unique index still refuses the write: nothing is written.
    await db().collection('artists').updateOne({ _id: holder }, { $set: { lifecycleStatus: 'deleting' } });
    const withHolder = await catalogState();
    await assert.rejects(applyArtists(), code('ADMIN_CATALOG_REVIEW_IDENTITY_CHANGED'));
    assert.equal(await catalogState(), withHolder);
    await db().collection('artists').deleteOne({ _id: holder });
    assert.equal(await catalogState(), before);
    // A member's credited Artist or the Album's renamed during the review: the source changed, and applying writes nothing.
    for (const renamed of [memberSinger, artist]) {
        const name = (await record('artists', renamed)).name;
        await db().collection('artists').updateOne({ _id: renamed }, { $set: { name: `${name} Renamed` } });
        const review = await current(id);
        assert.deepEqual([review.item.sourceStatus, review.item.capabilities.apply], ['changed', false]);
        // A stale review shows no confirmation either.
        await assert.rejects(candidatesOf(id), code('ADMIN_CATALOG_REVIEW_SOURCE_CHANGED'));
        const prior = await catalogState();
        await assert.rejects(applyArtists(), code('ADMIN_CATALOG_REVIEW_SOURCE_CHANGED'));
        assert.equal(await catalogState(), prior);
        await db().collection('artists').updateOne({ _id: renamed }, { $set: { name } });
        assert.equal((await current(id)).item.sourceStatus, 'current');
    }
    assert.equal((await applyArtists()).item.state, 'applied');
    assert.deepEqual([(await record('artists', artist)).musicBrainzId, (await record('albums', album)).credits], [lookupMbid(30), JSON.parse(before)[0][1][0].credits]);
}));

test('Artist entries and the label take the positions of the Credits they replace, keep every other Credit in order, keep phrases with unchanged successors, and replace the first label', () => withLookup(async () => {
    const composer = new ObjectId(), featured = new ObjectId(), oldLabel = new ObjectId(), secondLabel = new ObjectId();
    await db().collection('artists').insertMany([{ _id: composer, name: 'Synthetic Composer', lifecycleStatus: 'ready' }, { _id: featured, name: 'Synthetic Featured', lifecycleStatus: 'ready' }]);
    await db().collection('organizations').insertMany([{ _id: oldLabel, name: 'Old Label', organizationType: 'label', lifecycleStatus: 'ready' }, { _id: secondLabel, name: 'Second Label', organizationType: 'label', lifecycleStatus: 'ready' }]);
    await db().collection('albums').updateOne({ _id: album }, { $set: { credits: [
        { creditId: 'album_composer', subjectType: 'artist', subjectId: String(composer), role: 'composer', order: 0 },
        { creditId: 'primary_artist', subjectType: 'artist', subjectId: String(artist), role: 'primary', order: 1, joinPhrase: ' & ' },
        { creditId: 'album_featured', subjectType: 'artist', subjectId: String(featured), role: 'featured', order: 2 },
        { creditId: 'album_label_1', subjectType: 'organization', subjectId: String(oldLabel), role: 'label', order: 3, joinPhrase: ' / ' },
        { creditId: 'album_label_2', subjectType: 'organization', subjectId: String(secondLabel), role: 'label', order: 4 }] } });
    const guest: CreditedArtist = [lookupMbid(31), 'Lookup Guest'];
    const { id } = await completedReview(run({ releaseArtists: [[lookupMbid(30), 'Existing Artist'], guest] }));
    // A primary in place of the saved featured entry, and another label, are each one conflict; both are answered with lookup.
    await answer(id, ['album.artists', 'album.label'], 'lookup');
    const shown = await candidatesOf(id);
    assert.deepEqual(shown.album?.next.map(credit => [credit.name, credit.role, credit.joinPhrase, credit.creditId]), [['Synthetic Composer', 'composer', null, 'album_composer'],
        ['Existing Artist', 'primary', ' & ', 'primary_artist'], ['Lookup Guest', 'primary', null, null], ['Looked Up Label', 'label', ' / ', null], ['Second Label', 'label', null, 'album_label_2']]);
    assert.deepEqual([shown.album?.replacedPrimaryArtistIds, shown.album?.membersNamingReplaced], [[], []]);
    await applyShown(id, [field('artists'), field('label')]);
    const albumAfter = await record('albums', album), created = (await db().collection('artists').findOne({ name: 'Lookup Guest' }))!;
    const label = (await db().collection('organizations').findOne({ name: 'Looked Up Label' }))!;
    assert.deepEqual(albumAfter.credits.map((credit: any) => [credit.creditId.startsWith('review_') ? 'new' : credit.creditId, credit.subjectId, credit.role, credit.order, credit.joinPhrase]), [
        ['album_composer', String(composer), 'composer', 0, undefined], ['primary_artist', String(artist), 'primary', 1, ' & '], ['new', String(created._id), 'primary', 2, undefined],
        ['new', String(label._id), 'label', 3, ' / '], ['album_label_2', String(secondLabel), 'label', 4, undefined]]);
    // Primary Artists hold the Album in albumIds; the replaced featured Artist and the composer never did.
    assert.deepEqual([(await record('artists', artist)).albumIds, created.albumIds, created.musicBrainzId, (await record('artists', featured)).albumIds],
        [[String(album)], [String(album)], guest[0], undefined]);
    assert.equal(albumAfter.attributionStatus, 'documented');
}));

