test('a write failing late in the apply, or Credit writes turned off, leaves no record, ID, Credit, tracklist or receipt behind; the same apply is then admitted once', () => withLookup(async () => {
    const { id, _id, slots } = await completedReview(run({ tracks: [[singer], [singer]] }));
    const fields = [field('artists'), field('label'), field('expectedTracklist'), ...slots.map(slotId => field('discNumber', slotId))];
    const read = await candidatesOf(id), shown = shownFor(read, ['album.artists', ...slots.map(slotId => `tracks.${slotId}.artists`)], true);
    const body = { ...mutation((await current(id)).item.revision), fields, memberCredits: slots, ...shown, expectedValueRevision: read.valueRevision };
    const before = await catalogState(), review = await importCollection().findOne({ _id });
    const original = Collection.prototype.updateOne;
    // The Album's own update is the last catalog write: it fails after the new records, IDs and Credits were written in the transaction.
    const failing = mock.method(Collection.prototype, 'updateOne', async function (this: Collection, ...args: Parameters<Collection['updateOne']>) {
        if (this.collectionName === 'albums' && JSON.stringify(args[1]).includes('expectedTracklist')) throw new Error('synthetic late failure');
        return original.apply(this, args);
    });
    try { await assert.rejects(applyCatalogReview(String(actor), id, body), /synthetic late failure/); } finally { failing.mock.restore(); }
    assert.equal(await catalogState(), before);
    assert.deepEqual(await importCollection().findOne({ _id }), review);
    // Credit writes turned off refuse before any write, as the route's 503.
    process.env.CATALOG_CREDIT_WRITES_ENABLED = 'false';
    try {
        const refused = await request(`/catalog-reviews/${id}/apply`, 'POST', body);
        assert.deepEqual([refused.status, await refused.json()], [503, { code: 'ADMIN_CATALOG_REVIEW_UNAVAILABLE' }]);
    } finally { delete process.env.CATALOG_CREDIT_WRITES_ENABLED; }
    assert.equal(await catalogState(), before);
    const applied = await applyCatalogReview(String(actor), id, body);
    assert.deepEqual([applied.item.state, await db().collection('artists').countDocuments({ name: 'Track Singer' }), await db().collection('organizations').countDocuments()], ['applied', 1, 1]);
    assert.deepEqual(await applyCatalogReview(String(actor), id, body), applied);
}));

