/** `exchanges` with the release's first artist credit joined to the next by a featuring phrase, so the next one is featured. */
function featuring(exchanges: LookupExchange[]): LookupExchange[] {
    const release = exchanges.find(exchange => (exchange.body as { media?: unknown } | undefined)?.media !== undefined)!;
    (release.body as { 'artist-credit': { joinphrase: string }[] })['artist-credit'][0].joinphrase = ' feat. ';
    return exchanges;
}
/** The record ID an apply mints for a created identity (`key`, as reviewIdentityKey builds it) of review `id` in operation `operationId`. */
const createdRecordId = (id: string, operationId: string, key: string) => createHash('sha256').update(JSON.stringify({ catalogReview: id, operationId, identity: key })).digest('hex').slice(0, 24);
/** Decides `decisions` on review `id` at its current revision. */
const decideOn = async (id: string, decisions: unknown[]) => decideCatalogReviewIdentities(String(actor), id, { ...mutation((await current(id)).item.revision), decisions });
/** A completed run of the default Album's release `1` for a review whose Album has no Artist Credit (one search, by title only). */
const titleOnlyRun = (trackCount: number, options: Parameters<typeof creditedRelease>[1]) => [reviewSearch({ release: 'Existing Album' }, [[lookupMbid(1), trackCount]]), ...creditedRelease(lookupMbid(1), options)];

test('an Album without Artist Credits gains the release\'s artist as a preselected new Artist, applied over HTTP with an ID derived from the review, the operation and the identity', () => withLookup(async () => {
    await db().collection('albums').updateOne({ _id: album }, { $set: { credits: [], attributionStatus: 'unknown' } });
    const released: CreditedArtist = [lookupMbid(60), 'Released Artist'];
    const { id } = await completedReview(titleOnlyRun(2, { releaseArtists: [released], label: null }));
    const shown = await candidatesOf(id), row = shown.identities[0];
    assert.deepEqual([shown.identities.length, row.name, row.state, row.needsAnswer, row.preselection?.action, row.preselection?.candidateId, row.musicBrainzIdWrite],
        [1, 'Released Artist', 'unbound', false, 'create-distinct', null, { scope: 'artist', identity: row.id, musicBrainzId: released[0], replaces: null }]);
    assert.deepEqual(shown.album?.next.map(credit => [credit.name, credit.role, credit.creditId, credit.subjectId]), [['Released Artist', 'primary', null, null]]);
    const body = { ...mutation((await current(id)).item.revision), fields: [field('artists')], preselections: shown.preselections, musicBrainzIds: shown.musicBrainzIds,
        expectedValueRevision: shown.valueRevision };
    const response = await request(`/catalog-reviews/${id}/apply`, 'POST', body), value = await response.json();
    assert.deepEqual([response.status, value.item.state, value.receipt.kind], [200, 'applied', 'apply']);
    assert.match(response.headers.get('cache-control')!, /no-store/);
    const createdId = createdRecordId(id, body.operationId, `id:${released[0]}`), created = await record('artists', createdId);
    assert.deepEqual([created.name, created.musicBrainzId, created.albumIds, created.visibility, created.lifecycleStatus], ['Released Artist', released[0], [String(album)], 'hidden', 'ready']);
    const albumAfter = await record('albums', album);
    assert.deepEqual([albumAfter.credits, albumAfter.attributionStatus], [[{ creditId: reviewCreditId({ catalogReview: id, operationId: body.operationId, owner: 'album', entryKey: row.entries[0].entryKey }),
        subjectType: 'artist', subjectId: createdId, role: 'primary', order: 0 }], 'documented']);
    // Replaying the request answers the same response and mints nothing again.
    assert.deepEqual(await (await request(`/catalog-reviews/${id}/apply`, 'POST', body)).json(), value);
    assert.equal(await db().collection('artists').countDocuments({ name: 'Released Artist' }), 1);
}));

test('a bound identity\'s Artist keeps the MusicBrainz ID it holds until a decision replaces it, which only that record at its captured revision answers', () => withLookup(async () => {
    await db().collection('artists').updateOne({ _id: artist }, { $set: { musicBrainzId: lookupMbid(77) } });
    const { id } = await completedReview(run({ label: null }));
    // The release credits the Album's Artist under another ID: an ID conflict, which holds applying the entries until answered.
    await assert.rejects(applyShown(id, [field('artists')]), code('ADMIN_IMPORT_REVIEW_REQUIRED'));
    await answer(id, ['album.artists'], 'lookup');
    let shown = await candidatesOf(id);
    const rowOf = (value: CatalogReviewIdentityResponse) => value.identities.find(item => item.musicBrainzId === lookupMbid(30))!, row = rowOf(shown);
    assert.deepEqual([row.state, row.bound.map(item => [item.id, item.musicBrainzId]), row.needsAnswer, row.preselection, row.musicBrainzIdWrite, shown.album?.credits],
        ['bound', [[String(artist), lookupMbid(77)]], false, null, null, false]);
    const replace = { scope: 'artist', identity: row.id, boundName: 'Existing Artist', action: 'replace', candidateId: String(artist), candidateRevision: row.bound[0].revision };
    // A bound identity is answered only by replacing its own record's ID at the captured revision.
    for (const wrong of [{ ...replace, action: 'reuse' }, { ...replace, action: 'create-distinct', candidateId: null, candidateRevision: null }, { ...replace, candidateRevision: 'f'.repeat(64) },
        { ...replace, candidateId: String(new ObjectId()) }]) await assert.rejects(decideOn(id, [wrong]), code('ADMIN_IMPORT_INVALID_INPUT'), JSON.stringify(wrong));
    await decideOn(id, [replace]);
    shown = await candidatesOf(id);
    assert.deepEqual([rowOf(shown).decision?.action, rowOf(shown).musicBrainzIdWrite], ['replace', { scope: 'artist', identity: row.id, musicBrainzId: lookupMbid(30), replaces: lookupMbid(77) }]);
    const before = await record('albums', album);
    assert.equal((await applyShown(id, [field('artists')])).item.state, 'applied');
    // Only the ID changed: the Album's Credits and their revision are untouched.
    const after = await record('albums', album);
    assert.deepEqual([(await record('artists', artist)).musicBrainzId, after.credits, after.creditRevision], [lookupMbid(30), before.credits, before.creditRevision]);
}));

test('bound entries naming different Artists are one conflicting identity: it records no ID, its unbound entry waits for reuse or create, and one list never reuses one Artist twice', () => withLookup(async () => {
    const twin = new ObjectId();
    await db().collection('artists').insertOne({ _id: twin, name: 'Existing Artist', lifecycleStatus: 'ready', visibility: 'public' });
    await db().collection('audioTracks').updateOne({ _id: first }, { $set: { attributionStatus: 'documented', credits: [{ creditId: 'twin_primary', subjectType: 'artist', subjectId: String(twin), role: 'primary', order: 0 }] } });
    const existing: CreditedArtist = [lookupMbid(30), 'Existing Artist'], guest: CreditedArtist = [lookupMbid(66), 'Other Singer'];
    const { id, slots } = await completedReview(run({ tracks: [[existing], [existing, guest]] }));
    let shown = await candidatesOf(id);
    const rowOf = (value: CatalogReviewIdentityResponse, musicBrainzId: string) => value.identities.find(item => item.musicBrainzId === musicBrainzId)!, row = rowOf(shown, existing[0]);
    assert.deepEqual([row.state, row.bound.map(item => item.id).sort(), row.entries.map(entry => entry.slotId), row.needsAnswer, row.preselection, row.musicBrainzIdWrite],
        ['conflicting', [String(artist), String(twin)].sort(), [null, slots[0], slots[1]], true, null, null]);
    assert.equal(shown.musicBrainzIds.some(write => write.musicBrainzId === existing[0]), false);
    const before = await catalogState();
    await assert.rejects(applyShown(id, [field('artists')], slots), code('ADMIN_IMPORT_REVIEW_REQUIRED'));
    const reuse = (identity: string, boundName: string) => ({ scope: 'artist', identity, boundName, action: 'reuse', candidateId: String(artist), candidateRevision: row.bound.find(item => item.id === String(artist))!.revision });
    // Replacing is never an answer for a conflicting identity, and two entries of the second member's list may not reuse one Artist.
    await assert.rejects(decideOn(id, [{ ...reuse(row.id, 'Existing Artist'), action: 'replace' }]), code('ADMIN_IMPORT_INVALID_INPUT'));
    await assert.rejects(decideOn(id, [reuse(row.id, 'Existing Artist'), reuse(rowOf(shown, guest[0]).id, 'Other Singer')]), code('ADMIN_IMPORT_INVALID_INPUT'));
    await decideOn(id, [reuse(row.id, 'Existing Artist')]);
    shown = await candidatesOf(id);
    assert.deepEqual([rowOf(shown, existing[0]).needsAnswer, rowOf(shown, existing[0]).decision?.candidateId, rowOf(shown, existing[0]).musicBrainzIdWrite, rowOf(shown, guest[0]).preselection?.action],
        [false, String(artist), null, 'create-distinct']);
    assert.equal(await catalogState(), before);
    await applyShown(id, [field('artists')], slots);
    const created = (await db().collection('artists').findOne({ name: 'Other Singer' }))!;
    // Each bound entry keeps its own Artist; the unbound one takes the decided record; no Artist of the identity gains its ID.
    assert.deepEqual([(await record('albums', album)).credits.map((credit: any) => credit.subjectId), (await record('audioTracks', first)).credits.map((credit: any) => credit.subjectId),
        (await record('audioTracks', second)).credits.map((credit: any) => [credit.subjectId, credit.joinPhrase ?? null])],
        [[String(artist)], [String(twin)], [[String(artist), ' & '], [String(created._id), null]]]);
    assert.deepEqual([(await record('artists', artist)).musicBrainzId, (await record('artists', twin)).musicBrainzId, created.musicBrainzId, created.albumIds], [undefined, undefined, guest[0], []]);
}));

