test('a transient transaction error re-runs the apply against fresh state, which mints each record once with the same ID', () => withLookup(async () => {
    const { id, slots } = await completedReview(run({ tracks: [[singer], [singer]] }));
    const read = await candidatesOf(id), shown = shownFor(read, ['album.artists', ...slots.map(slotId => `tracks.${slotId}.artists`)], true);
    const body = { ...mutation((await current(id)).item.revision), fields: [field('artists'), field('label')], memberCredits: slots, ...shown, expectedValueRevision: read.valueRevision };
    const original = ClientSession.prototype.withTransaction;
    let attempts = 0;
    // The first attempt runs every write, then fails with a transient error: the driver aborts it and runs the change again.
    const transient = mock.method(ClientSession.prototype, 'withTransaction', function (this: ClientSession, ...args: Parameters<ClientSession['withTransaction']>) {
        const [work, options] = args;
        return original.call(this, async (session: ClientSession) => {
            const result = await work(session);
            if (++attempts === 1) { const error = new MongoError('Synthetic transient transaction error'); error.addErrorLabel('TransientTransactionError'); throw error; }
            return result;
        }, options);
    });
    let applied: CatalogReviewResponse;
    try { applied = await applyCatalogReview(String(actor), id, body); } finally { transient.mock.restore(); }
    assert.deepEqual([attempts, applied.item.state], [2, 'applied']);
    const createdId = createdRecordId(id, body.operationId, `id:${singer[0]}`);
    assert.deepEqual((await db().collection('artists').find({ name: 'Track Singer' }).toArray()).map(item => String(item._id)), [createdId]);
    assert.equal(await db().collection('organizations').countDocuments(), 1);
}));

test('an apply that commits but reports an unknown commit result replays its receipt for the same intent and mints nothing again', () => withLookup(async () => {
    const original = ClientSession.prototype.withTransaction;
    const again = await completedReview(run({ tracks: [[held], [held]] }));
    const readAgain = await candidatesOf(again.id), shownAgain = shownFor(readAgain, again.slots.map(slotId => `tracks.${slotId}.artists`), false);
    const replayed = { ...mutation((await current(again.id)).item.revision), fields: [], memberCredits: again.slots, ...shownAgain, expectedValueRevision: readAgain.valueRevision };
    let lost = true;
    const unknown = mock.method(ClientSession.prototype, 'withTransaction', async function (this: ClientSession, ...args: Parameters<ClientSession['withTransaction']>) {
        const result = await original.apply(this, args);
        if (lost) { lost = false; throw Object.assign(new Error('Synthetic unknown commit result'), { hasErrorLabel: (label: string) => label === 'UnknownTransactionCommitResult' }); }
        return result;
    });
    try { await assert.rejects(applyCatalogReview(String(actor), again.id, replayed), /Synthetic unknown commit result/); } finally { unknown.mock.restore(); }
    const committed = await catalogState();
    assert.equal(await db().collection('artists').countDocuments({ name: 'Held Singer' }), 1);
    assert.equal((await applyCatalogReview(String(actor), again.id, replayed)).receipt?.operationId, replayed.operationId);
    assert.equal(await catalogState(), committed);
    // Another body under that operation conflicts, and a new intent finds the review applied.
    await assert.rejects(applyCatalogReview(String(actor), again.id, { ...replayed, memberCredits: [again.slots[0]] }), code('ADMIN_IMPORT_OPERATION_CONFLICT'));
    await assert.rejects(applyCatalogReview(String(actor), again.id, { ...replayed, ...mutation((await current(again.id)).item.revision) }), code('ADMIN_CATALOG_REVIEW_APPLIED'));
}));

