        if (this.collectionName === 'artists' && JSON.stringify(args[0] ?? {}).includes('"name":')) throw new MongoServerError({ code: 50, codeName: 'MaxTimeMSExpired', errmsg: 'Synthetic time limit exceeded' });
        return original.apply(this, args);
