test('a decided replace whose new ID another record took shows its row again; the same set is stale, and a set without it applies with the old ID kept', () => withLookup(async () => {
    await db().collection('artists').updateOne({ _id: artist }, { $set: { musicBrainzId: lookupMbid(77) } });
    const { id } = await completedReview(run({ label: null }));
    await answer(id, ['album.artists'], 'lookup');
    const rowOf = (value: CatalogReviewIdentityResponse) => value.identities.find(item => item.musicBrainzId === lookupMbid(30))!, row = rowOf(await candidatesOf(id));
    const replace = { scope: 'artist', identity: row.id, boundName: 'Existing Artist', action: 'replace', candidateId: String(artist), candidateRevision: row.bound[0].revision };
    await decideOn(id, [replace]);
    // Another ready Artist takes the new ID: the replace can no longer apply, so its row needs an answer and the apply waits for it.
    await db().collection('artists').insertOne({ _id: new ObjectId(), name: 'Later Holder', lifecycleStatus: 'ready', visibility: 'public', musicBrainzId: lookupMbid(30) });
    const shown = await candidatesOf(id);
    assert.deepEqual([rowOf(shown).decision?.action, rowOf(shown).needsAnswer, rowOf(shown).musicBrainzIdWrite, shown.musicBrainzIds], ['replace', true, null, []]);
    const before = await catalogState();
    await assert.rejects(applyShown(id, [field('artists')]), code('ADMIN_IMPORT_REVIEW_REQUIRED'));
    // Sending the same replace again is stale; a set without it is the answer: the Artist keeps the ID it holds.
    await assert.rejects(decideOn(id, [replace]), code('ADMIN_IMPORT_DUPLICATE_STALE'));
    await decideOn(id, []);
    assert.deepEqual([rowOf(await candidatesOf(id)).needsAnswer, rowOf(await candidatesOf(id)).decision], [false, null]);
    assert.equal(await catalogState(), before);
    assert.equal((await applyShown(id, [field('artists')])).item.state, 'applied');
    assert.equal((await record('artists', artist)).musicBrainzId, lookupMbid(77));
}));

