test('a confirmation read while a run was queued is refused once the run wrote other values without changing the review revision, writing nothing', () => withLookup(async () => {
    const { id, slots } = await completedReview(run({ tracks: [[singer], [singer]] }));
    // A retried run is queued: its receipt raises the revision floor, and the confirmation is read before the run's values land.
    await retryCatalogReviewLookup(String(actor), id, mutation((await current(id)).item.revision));
    const read = await candidatesOf(id), revision = (await current(id)).item.revision;
    const fields = [field('expectedTracklist'), ...slots.map(slotId => field('discNumber', slotId))];
    const retried = creditedRelease(lookupMbid(2), { tracks: [[singer], [singer]] }), release = retried[0].body as { media: { tracks: { title: string }[] }[] };
    for (const track of release.media[0].tracks) track.title = track.title.replace('Looked Up', 'Retried');
    await drainLookup([...reviewSearches([[lookupMbid(2), 2]]), ...retried]);
    const after = await current(id);
    assert.deepEqual([after.item.revision, after.item.draft.album.expectedTracklist?.map(row => row.title)], [revision, ['Retried Track 1', 'Retried Track 2']]);
    const before = await catalogState();
    const body = { ...mutation(revision), fields, memberCredits: slots, ...shownFor(read, slots.map(slotId => `tracks.${slotId}.artists`), false), expectedValueRevision: read.valueRevision };
    await assert.rejects(applyCatalogReview(String(actor), id, body), code('ADMIN_IMPORT_REVISION_CONFLICT'));
    assert.equal(await catalogState(), before);
    // A confirmation read now applies the tracklist the run wrote.
    assert.equal((await candidatesOf(id)).valueRevision, read.valueRevision + 1);
    await applyShown(id, fields, slots);
    assert.deepEqual((await record('albums', album)).expectedTracklist.rows.map((row: { title: string }) => row.title), ['Retried Track 1', 'Retried Track 2']);
}));

