test('an apply racing another identity writer on the fence is retried against fresh state and shows the row again, so no second record is created', () => withLookup(async () => {
    for (const racer of [{ name: 'Track Singer', musicBrainzId: singer[0] }, { name: 'Track Singer' }]) {
        for (const name of ['adminAlbumImports', 'adminImportLookups', 'artists', 'organizations']) await db().collection(name).deleteMany(name === 'artists' ? { _id: { $ne: artist } } : {});
        const { id, slots } = await completedReview(run({ tracks: [[singer], [singer]], label: null }));
        const read = await candidatesOf(id);
        assert.equal(read.identities.find(item => item.musicBrainzId === singer[0])?.preselection?.action, 'create-distinct');
        const body = { ...mutation((await current(id)).item.revision), fields: [], memberCredits: slots, ...shownFor(read, slots.map(slotId => `tracks.${slotId}.artists`), false),
            expectedValueRevision: read.valueRevision };
        const original = Collection.prototype.updateOne;
        let fenceWrites = 0, raced = '';
        // Between this apply's identity reads and its fence write, another writer commits a record for the identity and bumps the fence.
        const racing = mock.method(Collection.prototype, 'updateOne', async function (this: Collection, ...args: Parameters<Collection['updateOne']>) {
            if (this.collectionName === 'adminImportAnalysisSlots' && ++fenceWrites === 1) {
                const other = getDatabaseClient().startSession();
                try {
                    await other.withTransaction(async () => {
                        await db().collection('artists').insertOne({ _id: new ObjectId(), lifecycleStatus: 'ready', visibility: 'public', ...racer }, { session: other });
                        // The driver's typings end with a callback overload; the promise form takes three arguments.
                        await original.apply(db().collection('adminImportAnalysisSlots'), [{ _id: 'identity' as any }, { $inc: { revision: 1 } }, { session: other, upsert: true }] as unknown as Parameters<Collection['updateOne']>);
                    });
                } finally { await other.endSession(); }
                raced = await catalogState();
            }
            return original.apply(this, args);
        });
        try { await assert.rejects(applyCatalogReview(String(actor), id, body), code('ADMIN_IMPORT_REVIEW_REQUIRED'), JSON.stringify(racer)); } finally { racing.mock.restore(); }
        // The first attempt conflicted on the fence and was retried; the retry saw the racing record and wrote nothing.
        assert.equal(fenceWrites, 1, JSON.stringify(racer));
        assert.equal(await catalogState(), raced, JSON.stringify(racer));
        assert.deepEqual([await db().collection('artists').countDocuments({ name: 'Track Singer' }), await db().collection('artists').countDocuments({ musicBrainzId: singer[0] })],
            [1, racer.musicBrainzId ? 1 : 0], JSON.stringify(racer));
        assert.equal((await candidatesOf(id)).identities.find(item => item.musicBrainzId === singer[0])?.needsAnswer, !racer.musicBrainzId, JSON.stringify(racer));
    }
}));

test('a review keeps its last receipt for applying: other changes stop one receipt early, and the apply is still admitted', () => withLookup(async () => {
    const { id, _id, slots } = await completedReview(run({ tracks: [[singer], [singer]] }));
    const stored = (await importCollection().findOne({ _id }))!;
    await importCollection().updateOne({ _id }, { $set: { receipts: [...stored.receipts, ...Array.from({ length: 255 - stored.receipts.length }, (_unused, index) => ({ operationId: randomUUID(),
        kind: 'edit', revision: stored.revision, actorId: String(actor), hash: `h${index}`, at: new Date() }))] } } as any);
    await assert.rejects(decideOn(id, []), code('ADMIN_IMPORT_OPERATION_LIMIT'));
    const applied = await applyShown(id, [field('artists')], slots);
    assert.deepEqual([applied.item.state, (await importCollection().findOne({ _id }))!.receipts.length], ['applied', 256]);
}));

test('an expected tracklist or pairing-filled numbers are refused while any stored pair cannot be read, writing nothing', () => withLookup(async () => {
    const { id, _id, slots } = await completedReview(run());
    const pairs = (await db().collection('adminImportLookups').findOne({ _id }))!.applied.pairs;
    await db().collection('adminImportLookups').updateOne({ _id }, { $set: { 'applied.pairs': [pairs[0], { ...pairs[1], trackNumber: 'two' }] } });
    const before = await catalogState(), discs = slots.map(slotId => field('discNumber', slotId));
    for (const fields of [[field('expectedTracklist'), ...discs], discs]) await assert.rejects(applyShown(id, fields), code('ADMIN_IMPORT_INVALID_INPUT'), JSON.stringify(fields));
    assert.equal(await catalogState(), before);
    await db().collection('adminImportLookups').updateOne({ _id }, { $set: { 'applied.pairs': pairs } });
    assert.equal((await applyShown(id, [field('expectedTracklist'), ...discs])).item.state, 'applied');
}));

test('the identity read names its default selection and the Album\'s kept expected tracklist', () => withLookup(async () => {
    // Every list that changed and the label, which an Album without a label Credit gains, are selected by default; no tracklist is kept.
    const { id, slots } = await completedReview(run({ tracks: [[singer], [singer]] }));
    const read = await candidatesOf(id);
    assert.deepEqual([read.selection, read.keptTracklist], [{ lists: ['album.artists', ...slots.map(slotId => `tracks.${slotId}.artists`)], label: true }, null]);
    // The selection is exactly what an apply of everything shows: its preselections and ID writes are the read's.
    assert.deepEqual(shownFor(read, read.selection.lists, read.selection.label), { preselections: read.preselections, musicBrainzIds: read.musicBrainzIds });
    // An Album keeping an expected tracklist: the read shows its rows as the review captured them.
    const rows = [{ discNumber: 1, trackNumber: 1, title: 'Track 1', durationMs: 60_000 }, { discNumber: 1, trackNumber: 2, title: 'Track 2', durationMs: null },
        { discNumber: 1, trackNumber: 3, title: 'Synthetic Missing Track', durationMs: null }];
    await db().collection('albums').updateOne({ _id: album }, { $set: { expectedTracklist: { source: 'musicbrainz', appliedAt: new Date('2026-10-20T08:00:00.000Z'), rows } } });
    const kept = await completedReview(run({ tracks: [[singer], [singer]] }));
    assert.deepEqual((await candidatesOf(kept.id)).keptTracklist, rows);
}));
